head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.resizeToWin();
        scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37703.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_rsn_OnLoadCompleted
 * @description grd_rsn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.grd_rsn_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37703.grd_rsn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_rsn_OnDblClick
 * @description grd_rsn 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_rsn_OnDblClick = async function(row, colid) {
    try {
        await scwin.setValue();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37703.grd_rsn_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37703.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let url = '';
    url += "&CD_ENG_NM=CPOC_DESIGN_RSN_CD";
    url += "&SCREN_ID=" + 'ULDSTF37703.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_rsn",
        action : "/ConfrmProcs.do",
        ref : "",
        target : "dts_rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 330;
    frame.Height = 330;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    panel_debug.hide();
};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setValue = async function() {
    const arrPar = new Array();
    if (scwin.fn_SetPar !== undefined) {
        arrPar[0] = dts_rsn.getCellData(dts_rsn.getRowPosition(), 2);
        arrPar[1] = dts_rsn.getCellData(dts_rsn.getRowPosition(), 3);
        scwin.fn_SetPar(arrPar);
    }
    await $c.win.closePopup();
};
